def select_memories(records, tenant_id, now, token_budget):
    eligible = [r for r in records if r['tenant_id'] == tenant_id and not r['deleted'] and r['expires_at'] > now]
    ranked = sorted(eligible, key=lambda r: (-(0.5*r['relevance'] + 0.3*r['reliability'] + 0.2*r['recency']), r['id']))
    selected, used = [], 0
    for record in ranked:
        cost = record['token_cost']
        if used + cost <= token_budget:
            selected.append({'id':record['id'], 'source_id':record['source_id'], 'score':0.5*record['relevance']+0.3*record['reliability']+0.2*record['recency']})
            used += cost
    return selected, used
